import { describe, expect, test } from "vitest";
import vectors from "./ua-vectors.json";
import { decodeUa, encodeOrchardUa, f4jumble, f4jumbleInv, orchardReceiverFromUa, parsePayoutAddress, type ZNetwork } from "../src/ua";

const hex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");

// Generated by web/tools/ua-vectors from crates/zol-zcash's encode_ua (Orchard-only UAs)
// and zcash_address 0.13 (multi-receiver UAs).
describe("unified address decoding against zol-zcash vectors", () => {
  for (const v of vectors) {
    test(`${v.network} ${v.kind}`, () => {
      if (v.orchard === null) {
        expect(() => orchardReceiverFromUa(v.ua)).toThrow(/no Orchard receiver/);
        return;
      }
      expect(hex(orchardReceiverFromUa(v.ua, v.network as ZNetwork))).toBe(v.orchard);
      expect(decodeUa(v.ua).network).toBe(v.network);
      if (v.kind.startsWith("orchard-only")) {
        // Our encoder reproduces encode_ua byte for byte.
        expect(encodeOrchardUa(Uint8Array.from(Buffer.from(v.orchard, "hex")), v.network as ZNetwork)).toBe(v.ua);
      }
    });
  }
});

test("wrong network is refused", () => {
  const v = vectors.find((x) => x.network === "mainnet" && x.orchard)!;
  expect(() => orchardReceiverFromUa(v.ua, "testnet")).toThrow(/mainnet/);
});

test("a corrupted character fails the bech32m checksum", () => {
  const v = vectors[0].ua;
  const i = v.length - 10;
  const bad = v.slice(0, i) + (v[i] === "q" ? "p" : "q") + v.slice(i + 1);
  expect(() => decodeUa(bad)).toThrow();
});

test("raw 43-byte receiver in hex is accepted", () => {
  const v = vectors[0];
  expect(hex(parsePayoutAddress(v.orchard!))).toBe(v.orchard);
  expect(hex(parsePayoutAddress(v.ua))).toBe(v.orchard);
  expect(() => parsePayoutAddress("abcd")).toThrow();
});

test("F4Jumble round-trips at several lengths", () => {
  for (const n of [48, 61, 128, 200, 1000]) {
    const m = Uint8Array.from({ length: n }, (_, i) => (i * 7 + 3) & 0xff);
    const j = f4jumble(m);
    expect(hex(j)).not.toBe(hex(m));
    expect(hex(f4jumbleInv(j))).toBe(hex(m));
  }
});
